 const messages={required:@json(__('ui.validation_required')),email:@json(__('ui.validation_email')),invalid:@json(__('ui.validation_invalid')),summary:@json(__('ui.validation_summary'))};
 const controls=form=>[...form.elements].filter(el=>el instanceof HTMLElement&&el.matches('input,select,textarea')&&!el.disabled&&!el.closest('[hidden]'));
 const messageFor=el=>{const v=el.validity;if(v.valueMissing||el.hasAttribute('required')&&!String(el.value??'').trim())return el.dataset.validationMessage||messages.required;if(v.typeMismatch)return messages.email;if(!v.valid)return messages.invalid;return null};
 const clearError=el=>{el.classList.remove('form-control-invalid');el.removeAttribute('aria-invalid');const id=el.dataset.validationErrorId;if(!id)return;document.getElementById(id)?.remove();const described=(el.getAttribute('aria-describedby')||'').split(/\s+/).filter(value=>value&&value!==id);if(described.length)el.setAttribute('aria-describedby',described.join(' '));else el.removeAttribute('aria-describedby');delete el.dataset.validationErrorId};
 const showError=(el,text)=>{clearError(el);el.classList.add('form-control-invalid');el.setAttribute('aria-invalid','true');const id='field-error-'+Math.random().toString(36).slice(2,10),node=document.createElement('small');el.dataset.validationErrorId=id;node.id=id;node.className='form-validation-error';node.textContent=text;const target=el.dataset.validationTarget?document.querySelector(el.dataset.validationTarget):null;const field=target||el.closest('.field')||el.parentElement;if(field)field.append(node);const described=(el.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean);el.setAttribute('aria-describedby',[...described,id].join(' '))};
 window.prepareCustomValidation=root=>root.querySelectorAll?.('form').forEach(form=>{form.noValidate=true;if(form.dataset.customValidationReady)return;form.dataset.customValidationReady='1';controls(form).forEach(el=>{const clearIfValid=()=>{if(form.dataset.validationAttempted&&!messageFor(el))clearError(el)};el.addEventListener('input',clearIfValid);el.addEventListener('change',clearIfValid)})});
 window.prepareCustomValidation(document);
 document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;form.noValidate=true;form.dispatchEvent(new Event('beforecustomvalidation'));const invalid=controls(form).map(el=>({el,message:messageFor(el)})).filter(item=>item.message);if(!invalid.length){controls(form).forEach(clearError);form.querySelector('[data-validation-summary]')?.remove();delete form.dataset.validationAttempted;return}form.dataset.validationAttempted='1';invalid.forEach(item=>showError(item.el,item.message));let summary=form.querySelector('[data-validation-summary]');if(!summary){summary=document.createElement('div');summary.className='form-validation-summary';summary.dataset.validationSummary='';summary.setAttribute('role','alert');summary.tabIndex=-1;form.prepend(summary)}summary.textContent=messages.summary;event.preventDefault();event.stopImmediatePropagation();const first=invalid[0].el,focusTarget=first.dataset.validationFocus?document.querySelector(first.dataset.validationFocus):first,scrollTarget=first.dataset.validationTarget?document.querySelector(first.dataset.validationTarget):first;focusTarget?.focus({preventScroll:true});scrollTarget?.scrollIntoView({behavior:'smooth',block:'center'})},{capture:true});
})();
</script>
<script>
(()=>{const dialog=document.getElementById('confirm-dialog'),message=document.getElementById('confirm-message'),accept=document.getElementById('confirm-accept'),cancel=document.getElementById('confirm-cancel');let pendingForm=null,pendingSubmitter=null;document.querySelectorAll('[data-confirmation-toast]').forEach(toast=>{const dismiss=()=>toast.remove();toast.addEventListener('click',dismiss);toast.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();dismiss()}});window.setTimeout(dismiss,5000)});document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!form.hasAttribute('data-confirm-submit'))return;if(form.dataset.confirmed==='1'){delete form.dataset.confirmed;return}event.preventDefault();event.stopImmediatePropagation();pendingForm=form;pendingSubmitter=event.submitter||null;message.textContent=form.dataset.confirmMessage||@json(__('ui.confirm_action'));dialog.returnValue='';dialog.showModal()},{capture:true});accept.addEventListener('click',()=>dialog.close('confirm'));cancel.addEventListener('click',()=>dialog.close('cancel'));dialog.addEventListener('close',()=>{if(dialog.returnValue!=='confirm'||!pendingForm){pendingForm=null;pendingSubmitter=null;return}const form=pendingForm,submitter=pendingSubmitter;pendingForm=null;pendingSubmitter=null;form.dataset.confirmed='1';if(submitter)form.requestSubmit(submitter);else form.requestSubmit()});})();
</script>
<script>
(()=>{const button=document.getElementById('music-toggle'),panel=document.getElementById('music-panel'),player=document.getElementById('music-player');if(!button)return;let started=false,playing=false;function command(name){player.contentWindow?.postMessage(JSON.stringify({event:'command',func:name,args:[]}),'*')}button.addEventListener('click',()=>{if(!started){player.src=player.dataset.src+'&autoplay=1';started=true;playing=true;panel.hidden=false;button.setAttribute('aria-expanded','true');button.textContent='♫ '+button.dataset.pause;return}panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));if(panel.hidden){command('pauseVideo');playing=false;button.textContent='♫ '+button.dataset.play}else if(!playing){command('playVideo');playing=true;button.textContent='♫ '+button.dataset.pause}else{command('pauseVideo');playing=false;button.textContent='♫ '+button.dataset.play}});})();
</script>
<script>
(()=>{if(!('serviceWorker'in navigator))return;navigator.serviceWorker.register('/service-worker.js',{scope:'/'}).catch(()=>{});let promptEvent;const installButton=document.getElementById('pwa-install');window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();promptEvent=event;if(installButton)installButton.hidden=false});installButton?.addEventListener('click',async()=>{if(!promptEvent)return;promptEvent.prompt();await promptEvent.userChoice;promptEvent=null;installButton.hidden=true});window.addEventListener('appinstalled',()=>{if(installButton)installButton.hidden=true})})();
</script>
<script>
(()=>{document.querySelectorAll('[data-flip-card]').forEach(button=>button.addEventListener('click',()=>{const card=button.closest('[data-priest-card]');const flipped=card.classList.toggle('is-flipped');card.querySelector('.priest-card-front').setAttribute('aria-hidden',flipped?'true':'false');card.querySelector('.priest-card-back').setAttribute('aria-hidden',flipped?'false':'true');card.querySelectorAll('[data-flip-card]').forEach(control=>control.setAttribute('aria-expanded',String(flipped)));}));})();
</script>
<script>
(()=>{document.addEventListener('click',event=>document.querySelectorAll('.nav-dropdown').forEach(menu=>{if(!menu.contains(event.target))menu.open=false}));document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.nav-dropdown').forEach(menu=>menu.open=false)});})();
</script>
<script>
(()=>{
 const mainSelector='#app-main';
 let busy=false;
 const runPageScripts=container=>container.querySelectorAll('script').forEach(old=>{const script=document.createElement('script');for(const attr of old.attributes)script.setAttribute(attr.name,attr.value);script.textContent=old.textContent;old.replaceWith(script)});
 const navigate=async(url,{replace=false,scroll=true,formData=null,method='GET'}={})=>{
  if(busy)return;busy=true;document.body.classList.add('is-navigating');
  try{
   const response=await fetch(url,{method,body:formData,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}});
   if(!response.ok && response.status>=500){window.location.assign(url);return;}
   const html=await response.text();const doc=new DOMParser().parseFromString(html,'text/html');
   const newMain=doc.querySelector(mainSelector),oldMain=document.querySelector(mainSelector);
   if(!newMain||!oldMain){window.location.assign(response.url||url);return;}
   oldMain.replaceWith(newMain);
   window.prepareCustomValidation?.(newMain);
   newMain.querySelectorAll('[data-confirmation-toast]').forEach(toast=>{const dismiss=()=>toast.remove();toast.addEventListener('click',dismiss);toast.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();dismiss()}});window.setTimeout(dismiss,5000)});
   const newNav=doc.querySelector('.nav'),oldNav=document.querySelector('.nav');if(newNav&&oldNav)oldNav.replaceWith(newNav);
   const newScripts=doc.querySelector('#page-scripts'),oldScripts=document.querySelector('#page-scripts');if(newScripts&&oldScripts){oldScripts.replaceWith(newScripts)}
   const newFooter=doc.querySelector('.footer'),oldFooter=document.querySelector('.footer');if(newFooter&&oldFooter)oldFooter.replaceWith(newFooter);
   document.title=doc.title;document.documentElement.lang=doc.documentElement.lang;
   const target=response.url||url;if(replace)history.replaceState({},'',target);else history.pushState({},'',target);
   if(newScripts)runPageScripts(newScripts);
   if(scroll){const hash=new URL(target).hash;if(hash)document.getElementById(decodeURIComponent(hash.slice(1)))?.scrollIntoView();else window.scrollTo({top:0,behavior:'instant'});}
   document.dispatchEvent(new CustomEvent('priestagenda:navigated',{detail:{url:target}}));
  }catch(error){window.location.assign(url)}finally{busy=false;document.body.classList.remove('is-navigating')}
 };
 const adminPaginationSections=['admin-page-size','admin-review-section','admin-priests-section','admin-history-section','admin-appointments-section'];
 const navigateAdminPagination=async url=>{if(busy)return;busy=true;document.body.classList.add('is-navigating');try{const response=await fetch(url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}});if(!response.ok)throw new Error('pagination');const doc=new DOMParser().parseFromString(await response.text(),'text/html');const replacements=adminPaginationSections.map(id=>[document.getElementById(id),doc.getElementById(id)]);if(replacements.some(([current,next])=>!current||!next))throw new Error('pagination');for(const [current,next] of replacements){current.replaceWith(next);window.prepareCustomValidation?.(next)}const target=response.url||url;history.pushState({},'',target);document.dispatchEvent(new CustomEvent('priestagenda:navigated',{detail:{url:target}}))}catch(error){const toast=document.createElement('div');toast.className='toast-confirmation warning';toast.setAttribute('role','status');toast.textContent=@json(__('ui.pagination_error'));document.body.append(toast);window.setTimeout(()=>toast.remove(),5000);toast.addEventListener('click',()=>toast.remove())}finally{busy=false;document.body.classList.remove('is-navigating')}};
 document.addEventListener('click',event=>{
  const link=event.target.closest('a[href]');if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||link.target==='_blank'||link.hasAttribute('download')||link.dataset.native!==undefined)return;
  const url=new URL(link.href,location.href);if(url.origin!==location.origin||url.pathname===location.pathname&&url.search===location.search&&url.hash)return;
  if(url.hash&&url.pathname===location.pathname&&url.search===location.search)return;
  if(link.closest('.admin-pagination')){event.preventDefault();navigateAdminPagination(url.href);return;}
  event.preventDefault();navigate(url.href);
 });
 document.addEventListener('submit',event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement)||form.target==='_blank'||form.dataset.native!==undefined)return;
  const url=new URL(form.action,location.href);if(url.origin!==location.origin)return;
  event.preventDefault();const method=(form.method||'GET').toUpperCase();const data=new FormData(form);
  if(form.id==='admin-page-size-form'){for(const [key,value] of data.entries()){if(typeof value==='string')url.searchParams.set(key,value)}navigateAdminPagination(url.href);return;}
  if(method==='GET'){for(const [key,value] of data.entries()){if(typeof value==='string')url.searchParams.set(key,value)}navigate(url.href);return;}
  const submitter=event.submitter;if(submitter?.name)data.append(submitter.name,submitter.value);
  navigate(url.href,{method,formData:data,scroll:false});
 });
 window.addEventListener('popstate',()=>navigate(location.href,{replace:true,scroll:true}));
})();
</script>
</body></html>
